import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import { expectFieldError, showRelatedList, waitForSpinners } from '../../support/lightning.js';
import { soqlCount } from '../../support/api.js';

test.describe('SF-219 Create Contact with empty Last Name (negative)', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-046 Create Contact with empty Last Name (negative)',
    { tag: ['@negative', '@P2', '@SF-219', '@persona:system-admin', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P2',
        severity: 'minor',
        feature: 'Contact',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-046',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const contactFirstName = data.unique('contact-first-name');
      await data.create('account-contact', ['Account']);
      await test.step("1. Click 'New Contact' button on the Account's Contacts related list", async () => {
        // Expected (DECLARED_CONFIG; OC-002, Field:Contact.LastName, SF-219#AC2, BRD-CON-012#BR-02): New Contact modal opens with Account Name pre-populated
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await expect(newContactDialog.root).toBeVisible();
      });
      await test.step('2. Enter First Name and leave Last Name empty', async () => {
        // Expected (DECLARED_CONFIG; OC-002, Field:Contact.LastName, SF-219#AC2, BRD-CON-012#BR-02): Last Name field is empty
        await newContactDialog.firstName.fill(contactFirstName);
        await expect(newContactDialog.lastName).toHaveValue('');
      });
      await test.step('3. Click Save', async () => {
        // Expected (DECLARED_CONFIG; OC-002, Field:Contact.LastName, SF-219#AC2, BRD-CON-012#BR-02): Contact is not saved; error message is displayed on the Last Name field indicating it is required
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await expect(newContactDialog.root).toBeVisible();
        await expectFieldError(newContactDialog.lastName);
        expect(await soqlCount(sf, 'Contact', 'FirstName', contactFirstName)).toBe(0);
        {
          const attempt = await data.attempt('Contact', {}, ['LastName']);
          expect(attempt.saved, 'Salesforce must reject this Contact').toBe(false);
          expect(attempt.errorCodes).toEqual(
            expect.arrayContaining([expect.stringMatching(/^(REQUIRED_FIELD_MISSING)$/)]),
          );
        }
      });
      await test.step('4. Verify the regression test MTC-002 passes with current component changes', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC2, BRD-CON-012#BR-02): Save is blocked and error is shown on Last Name field, confirming regression coverage
        await expect(newContactDialog.root).toBeVisible();
        await expectFieldError(newContactDialog.lastName);
      });
    },
  );
});
